  "Kırpılan kenar gizlenir, silinmez: içerik dosyada kalır. Gizli bilgiyi kaldırmak için kırpma yeterli değildir.": "The cropped edge is hidden, not deleted: the content stays in the file. Cropping is not enough to remove confidential information.",
