  "Doldurulacak PDF formunu buraya sürükleyin": "Drag the PDF form to fill here",
  "Düzleştir (alanlar sabit metne çevrilir, artık değiştirilemez)": "Flatten (fields become fixed text and can no longer be changed)",
  "Doldurulmuş PDF'i indir": "Download filled PDF",
