  "Baskı (300 DPI)": "Print (300 DPI)",
  "Görsellere çevir ve indir": "Convert to images and download",
  "Karartılacak PDF'i buraya sürükleyin": "Drag the PDF to redact here",
  "Karartılan bilgi dosyadan tamamen silinir; kopyalanamaz, aranamaz": "Redacted information is removed from the file entirely; it can't be copied or searched",
  "Hassas verileri bul": "Find sensitive data",
  "Büyük/küçük harf ve ş-s, ı-i, ğ-g, ç-c, ö-o, ü-u farkı gözetilmez": "Ignores case and the differences ş-s, ı-i, ğ-g, ç-c, ö-o, ü-u",
  "Karartılacak kelimeler (virgülle)": "Words to redact (comma-separated)",
  "Ara ve işaretle": "Search and mark",
  "◀ Önceki": "◀ Previous",
  "Sonraki ▶": "Next ▶",
  "Bu sayfadaki kutuları sil": "Delete boxes on this page",
  "Fareyle sürükleyerek kutu çizin; bir kutuya tıklayınca silinir. Otomatik bulunanları sayfa sayfa kontrol edin. Kelime aramasında büyük/küçük harf ve ş-s, ı-i gibi farklar gözetilmez: \"ayse\" yazınca \"AYŞE\" de bulunur.": "Drag with the mouse to draw a box; clicking a box deletes it. Check the automatically found ones page by page. Word search ignores case and differences like ş-s, ı-i: typing \"ayse\" also finds \"AYŞE\".",
  "İyi (200 DPI)": "Good (200 DPI)",
  "Bütün sayfaları resme çevir (hiçbir sayfada seçilebilir metin kalmaz)": "Convert all pages to images (no selectable text left on any page)",
  "Kutu içeren sayfalar resme çevrilir: o sayfalarda metin seçilemez ve aranamaz, dosya büyüyebilir. Belgenin yazar, başlık ve yer imi bilgileri yeni dosyaya taşınmaz.": "Pages with boxes are converted to images: text on those pages can't be selected or searched, and the file may grow. The document's author, title and bookmark information isn't carried over to the new file.",
  "Karartılmış PDF'i indir": "Download redacted PDF",
  "Taranmış PDF'i buraya sürükleyin": "Drag the scanned PDF here",
  "Sayfalardaki yazı tanınır; metni seçilebilen ve aranabilen bir PDF iner": "The text on the pages is recognised; you get a PDF whose text can be selected and searched",
  "Hızlı (200 DPI)": "Fast (200 DPI)",
  "Hassas (300 DPI)": "Accurate (300 DPI)",
  "Türkçe ve İngilizce tanınır. Sayfalar tarayıcınızda tek tek okunur; sayfa başına birkaç saniye sürebilir. Çıktıda her sayfa görüntü olarak kalır, üstüne görünmez metin katmanı eklenir.": "Turkish and English are recognised. Pages are read one by one in your browser; it may take a few seconds per page. In the output each page stays an image with an invisible text layer added on top.",
  "Metni tanı ve aranabilir PDF'i indir": "Recognise text and download searchable PDF",
  "Şifrelenecek ya da şifresi kaldırılacak PDF'i buraya sürükleyin": "Drag the PDF to encrypt or decrypt here",
  "Şifreli dosyada parolayla şifre kaldırılır; şifresiz dosyaya parola konur": "An encrypted file is decrypted with its password; an unencrypted file gets a password",
  "Açılış parolası": "Open password",
  "Parola tekrar": "Repeat password",
  "Parolayı açan kişinin yapabilecekleri:": "What the person who opens it with the password can do:",
  "Yazdırabilsin": "Can print",
  "Metin kopyalayabilsin": "Can copy text",
  "Değiştirebilsin": "Can modify",
  "Form doldurabilsin": "Can fill forms",
  "Kısıtlama seçerseniz kimsenin bilmediği rastgele bir yönetici parolası konur; kısıtlar sonradan kaldırılamaz. Şifreleme AES-256'dır. Parolayı unutursanız dosya açılamaz.": "If you choose restrictions, a random owner password that nobody knows is set; the restrictions can't be removed later. Encryption is AES-256. If you forget the password, the file can't be opened.",
  "Şifrele ve indir": "Encrypt and download",
  "Parola": "Password",
  "Parolayı biliyorsanız şifre kaldırılır; parola kırılmaz. Yalnız izinleri kısıtlanmış (açılış parolası olmayan) dosyada parolayı boş bırakın.": "If you know the password, the encryption is removed; passwords are not cracked. Leave the password empty only for a file with restricted permissions (no open password).",
  "Şifreyi kaldır ve indir": "Remove password and download",
  "PDFLib kütüphanesi yüklenemedi. Lütfen vendor/pdf-lib.min.js dosyasının mevcut olduğundan emin olun.": "The PDFLib library couldn't be loaded. Make sure vendor/pdf-lib.min.js exists.",
  "\"{0}\" karakteri PDF'in yerleşik yazı tipiyle yazılamıyor.": "The character \"{0}\" can't be written with the PDF's built-in font.",
  "Bu PDF şifreli (parola korumalı veya yazdırma/kopyalama izni kısıtlı).": "This PDF is encrypted (password protected or with restricted print/copy permissions).",
  "Önce \"Şifre\" sekmesinden parolasını girip şifresini kaldırın, sonra şifresiz kopyayla devam edin.": "First remove its password in the \"Password\" tab, then continue with the unencrypted copy.",
