  "Sayfa numarası biçimindeki \"{0}\" karakteri yazılamıyor. Türkçe ve Batı Avrupa harfleri, rakam ve noktalama kullanılabilir.": "The character \"{0}\" in the page number format can't be written. Turkish and Western European letters, digits and punctuation can be used.",
