  "Değerlerde PDF yazı tipinin yazamadığı karakterler (Kiril, emoji gibi) var; form düzleştirilemedi, alanlar düzenlenebilir kaldı.": "The values contain characters the PDF font can't write (such as Cyrillic or emoji); the form couldn't be flattened and the fields stay editable.",
  "Değerlerde PDF yazı tipinin yazamadığı karakterler (Kiril, emoji gibi) var; alan görünümünü PDF görüntüleyici çizecek.": "The values contain characters the PDF font can't write (such as Cyrillic or emoji); the PDF viewer will draw the field appearance.",
