  "Filigran için bir görsel seçin.": "Choose an image for the watermark.",
  "İlk sayfa {0} × {1} mm. Kenar payları sayfayı gördüğünüz yöne göredir.": "The first page is {0} × {1} mm. Margins follow the page as you see it.",
  "Bu PDF'te doldurulabilir form alanı yok. Taranmış ya da düz metin formlar için \"Filigran\" ve \"Düzenle\" araçlarını kullanabilirsiniz.": "This PDF has no fillable form fields. For scanned or plain-text forms you can use the \"Watermark\" and \"Organize\" tools.",
