  "{0} sayfada metin yok (taranmış olabilir): elle işaretleyin ya da önce OCR'dan geçirin.": "{0} pages have no text (they may be scanned): mark them manually or run OCR first.",
  "Karartılacak kelimeyi yazın.": "Enter the word to redact.",
