  "Karartılacak kutu yok. Fareyle kutu çizin ya da \"Hassas verileri bul\"u kullanın.": "There are no boxes to redact. Draw a box with the mouse or use \"Find sensitive data\".",
  "Sayfa {0} / {1} karartılıyor…": "Redacting page {0} / {1}…",
