  "{0} sayfa okundu ama yazı tanınmadı. Sayfa görüntüsü bulanık ya da yazısız olabilir.": "{0} pages read but no text was recognised. The page image may be blurry or have no text.",
  "şifreli": "encrypted",
  "şifresiz": "not encrypted",
  "PDF okunamadı: {0}": "The PDF couldn't be read: {0:t}",
  "Açılış parolası girin.": "Enter an open password.",
  "Parolalar aynı değil.": "The passwords don't match.",
  "Masko — Hızlı": "Masko — Quick",
  "Seçili metni maskeye ekle": "Add selected text to mask",
  "Maskele, kontrol et ve kopyala": "Mask, check and copy",
  "Maskeli çıktı": "Masked output",
  "Geri Aç ve Kopyala": "Unmask and Copy",
  "Hangi AI sitelerinde butonların aktif olacağını yönetin. Kapattığınız sitede buton ve uyarılar açık sekmelerde de hemen kapanır. Site erişim izni uzantının kurulum izinlerinin parçasıdır; buradan kaldırılamaz.": "Choose which AI sites show the buttons. On a site you turn off, the buttons and warnings switch off immediately in open tabs too. Site access permission is part of the extension's install permissions and can't be removed here.",
  "Masko'nun bütün sayfaları için geçerlidir. \"Sistem\" bilgisayarın açık/koyu ayarını izler.": "Applies to all Masko pages. \"System\" follows your computer's light/dark setting.",
  "Dil": "Language",
  "Arayüz dili. Masko'nun bütün sayfaları için geçerlidir.": "Interface language. Applies to all Masko pages.",
  "Yapıştırırken maskele": "Mask on paste",
  "Hassas veri içeren bir metni AI sitesine yapıştırdığınızda (Ctrl+V ya da sürükle-bırak) metin siteye ulaşmadan tarayıcınızda maskelenir; kutuya yalnızca [TCKN_1] gibi maskeli hâli yazılır. Site ham veriyi hiçbir aşamada görmez. Klavyeyle yazdığınız veri ise yazarken sitenin koduna görünür; onun için aşağıdaki gönderim uyarısı devrededir.": "When you paste text containing sensitive data into an AI site (Ctrl+V or drag and drop), the text is masked in your browser before it reaches the site; only the masked version, like [TCKN_1], is written into the box. The site never sees the raw data. Data you type on the keyboard, however, is visible to the site's code as you type; the pre-send warning below covers that.",
  "Yapıştırılan hassas veriyi otomatik maskele": "Automatically mask pasted sensitive data",
  "Gönderim öncesi uyarı": "Pre-send warning",
  "Yazarken kutuda maskelenmemiş TCKN, kart, şifre gibi hassas veriler kaldığında düğmede bir uyarı işareti gösterir. Böyle bir metinle Enter'a veya Gönder'e bastığınızda ilk basışı durdurup uyarır; aynı metinle tekrar basarsanız mesaj olduğu gibi gönderilir.": "While you type, shows a warning sign on the button when unmasked sensitive data such as ID numbers, cards or passwords remain in the box. When you press Enter or Send with such text, it stops the first press and warns you; if you press again with the same text, the message is sent as is.",
  "Gönderim öncesi uyarıyı etkinleştir": "Enable the pre-send warning",
  "Tam aracı aç: sözlük, dosya işleri, Veri Tezgâhı": "Open the full tool: dictionary, file tools, Data Workbench",
  "{0} kalan hassas aday. Panoya kopyalansın mı?": "{0} sensitive candidates remain. Copy to clipboard?",
  "Kopyalandı ✓ — hedef kutuya yapıştırın": "Copied ✓ — paste into the target box",
  "{0} kalan hassas aday bulundu. Son kontrolü onaylayıp kopyalamak istiyor musunuz?": "{0} sensitive candidates remain. Do you want to approve the final check and copy?",
  "Zaten sözlükte": "Already in the dictionary",
  "Kopyalandı ✓": "Copied ✓",
  "Yapıştırırken maskeleme açıldı ✓": "Mask on paste turned on ✓",
  "Yapıştırırken maskeleme kapatıldı — yapıştırılan veri siteye ham gider": "Mask on paste turned off — pasted data goes to the site raw",
  "Gönderim öncesi uyarı açıldı ✓": "Pre-send warning turned on ✓",
  "Gönderim öncesi uyarı kapatıldı": "Pre-send warning turned off",
  "Dosya okunamadı": "File could not be read",
  "csv-io.js yüklenmedi; CSV okunamaz/yazılamaz.": "csv-io.js is not loaded; CSV can't be read/written.",
  "başlık adı özel nitelikli bir veriyi işaret ediyor": "the header name points to special-category data",
  "başlık adından tanındı (hücre örüntüsü yok)": "recognized from the header name (no cell pattern)",
  "{0} hücrenin {1}'i checksum doğrulamasından geçti": "{1} of {0} cells passed checksum verification",
  "örüntü eşleşmesi %{0}": "pattern match {0}%",
