  "Güvenli takma ad için file-mask-engine.js yüklenmeli.": "file-mask-engine.js must be loaded for safe aliases.",
  "Bu veriden anlamlı görselleştirmeler üret. Hangi grafik tiplerinin uygun olduğunu gerekçesiyle söyle ve çalışır Python (pandas + matplotlib) kodu yaz.": "Produce meaningful visualizations from this data. Say which chart types are suitable and why, and write working Python (pandas + matplotlib) code.",
  "Bu veriyi keşifsel olarak analiz et: hangi sorular sorulmalı, hangi kırılımlara bakılmalı, hangi metrikler hesaplanmalı? Çalışır Python kodu ver.": "Analyse this data exploratively: which questions should be asked, which breakdowns should be examined, which metrics should be computed? Give working Python code.",
  "Bu veri setindeki olası kalite sorunlarını (eksik değer, aykırı değer, tip uyumsuzluğu, tekrarlı kayıt) tespit eden ve temizleyen Python kodu yaz.": "Write Python code that detects and cleans possible quality issues in this dataset (missing values, outliers, type mismatches, duplicate records).",
  "Bu veriden yönetim raporu için özet/pivot tablolar üret. Hangi kırılımların anlamlı olduğunu açıkla ve Python kodu ver.": "Produce summary/pivot tables for a management report from this data. Explain which breakdowns are meaningful and give Python code.",
  "Bu tablo yapısı için analiz sorguları yaz (SQL). Şema tanımını da ver.": "Write analysis queries (SQL) for this table structure. Also give the schema definition.",
  "Etkinlik ve tribün/blok bazında doluluk oranını (satılan / kapasite) hesaplayan ve görselleştiren kod yaz. Hangi kırılımların anlamlı olduğunu açıkla.": "Write code that computes and visualizes the occupancy rate (sold / capacity) by event and stand/block. Explain which breakdowns are meaningful.",
  "Satışa açılıştan etkinlik gününe kadar günlük/kümülatif satış eğrisini çıkar. Satışın hızlandığı ve yavaşladığı dönemleri işaretle; kategori bazında karşılaştır.": "Derive the daily/cumulative sales curve from the start of sales to the event day. Mark the periods where sales speed up and slow down; compare by category.",
  "Bilet satın alıp etkinliğe gelmeyen (no-show) oranını hesapla: satılan biletler ile turnike giriş kayıtlarını karşılaştır. No-show'un kategori, kanal ve satın alma zamanına göre değişimini incele.": "Compute the no-show rate (bought a ticket but didn't attend): compare sold tickets with turnstile entry records. Examine how no-shows vary by category, channel and purchase time.",
  "Satış kanalı (web / mobil / gişe / bayi) kırılımında hacim, ortalama sepet ve kategori dağılımını karşılaştıran analiz ve grafikler üret.": "Produce analysis and charts comparing volume, average basket and category distribution broken down by sales channel (web / mobile / box office / dealer).",
  "Müşteri bazında RFM (recency, frequency, monetary) segmentasyonu yap ve segmentleri görselleştir. Tekrar satın alma davranışını incele.": "Do an RFM (recency, frequency, monetary) segmentation per customer and visualize the segments. Examine repeat purchase behaviour.",
  "Kombine (sezonluk) sahiplerinin davranışını analiz et: yenileme oranı, maç başına katılım, tekil bilet alanlarla karşılaştırma.": "Analyse the behaviour of season ticket holders: renewal rate, attendance per match, comparison with single-ticket buyers.",
  "Fiyat kategorisi bazında talep esnekliğini incele; hangi kategorilerin erken dolduğunu, hangilerinin son güne kaldığını çıkar. Dinamik fiyatlama için öneri üret.": "Examine demand elasticity by price category; find which categories fill up early and which wait until the last day. Produce a recommendation for dynamic pricing.",
  "Anormal satın alma örüntülerini tespit et: aynı kimliğe/karta bağlı yüksek adetli alımlar, kısa sürede çok sayıda işlem, aynı koltuk bloğunun toplu alınması. Şüpheli işlemleri işaretleyen kod yaz.": "Detect abnormal purchase patterns: high-quantity purchases tied to the same ID/card, many transactions in a short time, bulk purchases of the same seat block. Write code that flags suspicious transactions.",
  "Kopya denetimi yapılamadı (hizalı gerçek satır örneği yok)": "Copy check could not run (no aligned real-row sample)",
  "NIST SP 800-226: Bu metrikler sentetik örneğin biçimsel ve istatistiksel tutarlılığını ölçer. Mutlak diferansiyel gizlilik (differential privacy) veya anonimlik garantisi değildir.": "NIST SP 800-226: These metrics measure the formal and statistical consistency of the synthetic sample. They are not a guarantee of differential privacy or anonymity.",
  "Satış tablosundaki tekil bilet anahtarını seçin.": "Pick the distinct ticket key in the sales table.",
  "Turnike tablosundaki bilet anahtarını seçin.": "Pick the ticket key in the turnstile table.",
  "Etkinlik eşleştirmesi için iki tabloda da etkinlik anahtarı seçin veya girdilerin tek etkinliğe filtrelendiğini onaylayın.": "For event matching, pick an event key in both tables or confirm the inputs are filtered to a single event.",
  "Geçerli satışları belirleyen durum kolonunu seçin.": "Pick the status column that identifies valid sales.",
  "Geçerli bilet durumlarının değerlerini yazın.": "Enter the values of valid ticket statuses.",
  "Payda kuralını seçin: önceden filtrelenmiş satış girdisi veya durum kolonu.": "Choose the denominator rule: pre-filtered sales input or status column.",
  "Satış girdisinden iptal/iade/geçersiz biletlerin çıkarıldığını onaylayın.": "Confirm that cancelled/refunded/invalid tickets are removed from the sales input.",
  "Turnike girdisinin yalnız başarılı girişleri içerdiğini onaylayın.": "Confirm the turnstile input contains only successful entries.",
