  "<0>Bu tablo kimliğe bağlı.</0> TC Kimlik No / pasaport / Passo Taraftar Kart kolonu içeriyor. Biletleme verisinde bu tesadüf değil: {0} sayılı Kanun gereği her bilet bir kimliğe tanımlanmak zorunda. Bu kolonların gerçek değerleri hiçbir koşulda gönderilmiyor ve bu ayar kapatılamıyor.": "<0>This table is identity-linked.</0> It contains a Turkish ID number / passport / Passo Fan Card column. In ticketing data this is no coincidence: under Turkish Law No. {0} every ticket must be tied to an identity. The real values of these columns are never sent, and this setting can't be turned off.",
  "<0>Tablolar arasında ortak anahtar bulunamadı.</0> Kolon adları farklıysa veya değerler örtüşmüyorsa join tespit edilemez — dosyaları ayrı ayrı analiz ettirmeniz gerekebilir.": "<0>No shared key found between the tables.</0> If the column names differ or the values don't overlap, a join can't be detected — you may need to have the files analysed separately.",
  "{0} ortak anahtar bulundu.": "{0} shared keys found.",
  "1 ortak anahtar bulundu.": "1 shared key found.",
  "Bu kolonlarda aynı gerçek değer her dosyada aynı sahte değere dönüşüyor — yani join'ler örnek veride de çalışıyor.": "In these columns the same real value becomes the same fake value in every file — so joins work on the sample data too.",
