  "Dosyayı şirket dışına veya ortaklara göndermeden önce tarayın. Gizli sayfaları, yorumları, formül açıklarını ve maskelenmemiş kalıntı PII'ları tespit edin.": "Scan the file before sending it outside the company or to partners. Detect hidden sheets, comments, formula risks and leftover unmasked PII.",
  "Güvenlik Denetimini Başlat": "Start Security Check",
  "<0>İlişkiyi koruyan maskeleme</0> <1>Tuzlu HMAC</1>": "<0>Relationship-preserving masking</0> <1>Salted HMAC</1>",
  "Farklı tablolardaki aynı kayıtlar aynı takma adı alır. Maskeli tablolar kendi aralarında güvenle JOIN edilebilir, ilişkisel bütünlük korunur.": "The same records in different tables get the same alias. Masked tables can be safely JOINed with each other; relational integrity is preserved.",
  "Kurumsal Gizli Tuz (Salt Anahtarı)": "Corporate Secret Salt (Salt Key)",
  "Maske Kasası, takma ad ↔ gerçek değer eşlemesini veriden ayrı bir dosyada saklar; maskeli tabloyu daha sonra geri açmanızı sağlar. Parola girerseniz kasa AES-256-GCM ile şifrelenir (parolasız kasa gerçek değerleri düz metin içerir).": "The Mask Vault stores the alias ↔ real value mapping in a file separate from the data, letting you unmask the masked table later. If you enter a password, the vault is encrypted with AES-256-GCM (a vault without a password contains the real values in plain text).",
  "Kasa parolası (en az 8 karakter, önerilir)": "Vault password (at least 8 characters, recommended)",
  "Bu oturumda üretilen takma adların kasasını indirir.": "Downloads the vault of aliases generated in this session.",
