  "- Kullanıcı iki girdinin de tek bir etkinliğe önceden filtrelendiğini onayladı; etkinlik anahtarıyla ayrıca eşleştirme yapma.": "- The user confirmed both inputs are pre-filtered to a single event; do not additionally match on an event key.",
  "- Etkinlik eşleştirmesi: {0}": "- Event matching: {0}",
  "- Kullanıcı satış girdisinin iptal/iade/geçersiz biletlerden arındırıldığını onayladı.": "- The user confirmed the sales input is cleared of cancelled/refunded/invalid tickets.",
  "- Geçerli satış filtresi: {0}": "- Valid-sale filter: {0}",
  "- Kullanıcı turnike girdisinin yalnız başarılı girişleri içerdiğini onayladı.": "- The user confirmed the turnstile input contains only successful entries.",
  "- Payda = geçerli tekil satılan bilet sayısı; pay = bunlardan en az bir başarılı girişi olan tekil bilet sayısı.": "- Denominator = distinct valid sold tickets; numerator = those with at least one successful entry.",
  "- No-show = payda − pay; oran = no-show / payda. Tekrarlı okutmalar bileti birden fazla sayma; sıfır paydada oranı null bırak.": "- No-show = denominator − numerator; rate = no-show / denominator. Do not count repeat scans more than once; leave the rate null on zero denominator.",
  "- Durum filtresinde baştaki/sondaki boşlukları temizle ve büyük-küçük harf farkını yok say. Çelişkili satış satırlarını sessizce tek duruma indirgeme; sayısını raporla.": "- Trim leading/trailing whitespace in the status filter and ignore case. Do not silently collapse conflicting sale rows to one status; report their count.",
  "- Etkinlik ve bilet anahtarıyla eşleştir; eşleşmeyen turnike kayıtlarını ayrı raporla. İptal/iade ve başarılı okutma tanımını verilen onay/kurala göre uygula.": "- Match on the event and ticket key; report unmatched turnstile records separately. Apply the cancellation/refund and successful-scan definitions per the given confirmation/rule.",
  "- Kategori, kanal ve satın alma zamanı kırılımlarını yalnızca seçili tablolarda mevcutsa kullan; eksik kolonları uydurma ve analiz kısıtını açıkça belirt.": "- Use category, channel and purchase-time breakdowns only where they exist in the selected tables; do not invent missing columns and state the analysis limitation explicitly.",
  "- EŞLEŞTİRME HAZIR DEĞİL. Kesin hesaplama veya çalıştırılabilir kod üretme; önce yalnızca aşağıdaki eksikleri kullanıcıya sor, varsayım uydurma:": "- MATCHING NOT READY. Do not produce a definitive number or runnable code; first ask the user only about the gaps below and invent no assumptions:",
  "NOT: Şu kolonların yorumundan emin değilim, kodda varsayımını açıkça belirt: {0}": "NOTE: I am not sure about the meaning of these columns; state your assumption explicitly in the code: {0}",
  "{0} MB — büyük dosya, ayrıştırma arka planda sürüyor…": "{0} MB — large file, parsing continues in the background…",
