  "Çıkarılan sütun tablodan ve indirilen dosyadan çıkar; veri silinmez, buradan geri getirilir. Çıkarılan sütuna göre yine tekilleştirebilirsiniz.": "A removed column leaves the table and the downloaded file; no data is deleted and it can be brought back here. You can still deduplicate by a removed column.",
  "Tümünü geri getir": "Bring all back",
  "Yeni sütun tablonun sonuna eklenir, tekilleştirme anahtarı olarak seçilebilir ve indirilen dosyaya yazılır. Yüklediğiniz dosya değişmez.": "The new column is added at the end of the table, can be chosen as a deduplication key and is written to the downloaded file. The file you loaded does not change.",
  "Ne eklensin?": "What should be added?",
  "Sütunları birleştir": "Combine columns",
  "Ör. ad + soyad → \"Ahmet Yılmaz\". Birlikte aynı olan satırları bulmak için anahtar olarak kullanılabilir.": "E.g. first name + last name → \"Ahmet Yılmaz\". Can be used as a key to find rows that match on all of them together.",
  "Tekrar sayısı": "Duplicate count",
  "Seçilen sütundaki değerin dosyada kaç kez geçtiği. Temizlikten sonra da ilk hâli gösterir.": "How many times the value in the chosen column appears in the file. It keeps showing the original count after cleaning.",
